import{_ as r,l as i,o as e,c as l,v as o,p as s,x as n,d as E,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"传染与系统性","description":"","frontmatter":{"title":"传染与系统性","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/bank-contagion.md","filePath":"econ/bank-contagion.md","lastUpdated":1789023840000}'),c={name:"econ/bank-contagion.md"};function h(A,a,B,m,_,u){const t=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=o('<h1 id="传染与系统性" tabindex="-1">传染与系统性 <a class="header-anchor" href="#传染与系统性" aria-label="Permalink to &quot;传染与系统性&quot;">​</a></h1><div class="epigraph"><p>一家银行的挤兑可以经由银行间债权写成另一家的挤兑；不完全的保险网络把区域冲击做成系统事件。</p><footer>—— Allen and Gale, Financial Contagion, Journal of Political Economy 2000</footer></div><p>定位：<a href="/econ/diamond-dybvig">上一课</a>。单家银行的活期合同已经允许与基本面无关的坏均衡。本课缺口是把银行放进一个<strong>彼此持有存款</strong>的系统：挤兑如何从一家传到另一家。不重推 \\(r_1\\) 与序贯服务，不问准备金乘数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Diamond–Dybvig 的银行是封闭的资产池。若耐心者只在本行排队，一家的坏均衡不必变成另一家的坏均衡。现实中银行用银行间存款互相保险：A 区今天急躁者偏多，向 B 区提款；B 区明天急躁者偏多，反向提。完全连接的网络可以把区域流动性冲击摊开。不完全连接时，冲击没有被摊开的出口，被迫提前清算长期技术，清算折扣写进对手的资产——传染开始。</p><p>缺口因此不是再讲一次太阳黑子，而是：在哪一种银行间结构下，单家挤兑的外部性变成系统性。Allen 与 Gale（2000）把这个问题收成市场结构，而不是「谣言传播」。</p><p><span class="marginnote">系统性不是「很多家同时倒」。它是一家的违约通过价格或债权改变另一家的可行集。同时倒可以是共同冲击；传染要求有一条可指认的传递边。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设若干区域，每区一家代表性银行，活期合同仍是上一课的保险。银行在 \\(t=0\\) 互相存放存款，作为跨区流动性保险。完全市场（每家持有所有其他家的存款）时，一区的超额提取由全系统分摊，没有一家需要中断长期技术。不完全市场（例如环形：每家只与邻居互存）时，冲击沿着环走：邻居先被抽干，再抽下一家。</p><p>清算有折扣：长期资产在 \\(t=1\\) 卖掉拿不到持有到期值。折扣使对手银行的银行间资产减值，于是对手也面对 Diamond–Dybvig 式的短债长资缺口。坏均衡可以在没有新的太阳黑子的情况下，被邻居的挤兑<strong>导入</strong>。</p>',10)),(e(),s(d,null,{default:n(()=>[p(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20SHOCK%5B%22%E4%B8%80%E5%8C%BA%E8%B6%85%E9%A2%9D%E6%8F%90%E5%8F%96%22%5D%20--%3E%20IB%5B%22%E9%93%B6%E8%A1%8C%E9%97%B4%E5%AD%98%E6%AC%BE%22%5D%0A%20%20IB%20--%3E%20COMP%5B%22%E5%AE%8C%E5%85%A8%E7%BD%91%E7%BB%9C%3A%20%E5%88%86%E6%91%8A%22%5D%0A%20%20IB%20--%3E%20INC%5B%22%E4%B8%8D%E5%AE%8C%E5%85%A8%E7%BD%91%E7%BB%9C%3A%20%E9%82%BB%E5%B1%85%E5%85%88%E8%A2%AB%E6%8A%BD%E5%B9%B2%22%5D%0A%20%20INC%20--%3E%20FIRE%5B%22%E6%8F%90%E5%89%8D%E6%B8%85%E7%AE%97%22%5D%0A%20%20FIRE%20--%3E%20NEXT%5B%22%E5%AF%B9%E6%89%8B%E8%B5%84%E4%BA%A7%E5%87%8F%E5%80%BC%22%5D%0A%20%20NEXT%20--%3E%20RUN2%5B%22%E5%AF%BC%E5%85%A5%E7%9A%84%E6%8C%A4%E5%85%91%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>Freixas、Parigi 与 Rochet 把同一逻辑写成支付系统里的信用暴露：未结算头寸是另一种银行间债权。本课只钉资产负债通道，支付通道留给 <a href="/econ/rtgs-payments">RTGS</a>。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是保险合同在网络上的外部性。银行间存款本意是硬币保险：平滑区域冲击。它同时是传递损失的导管。完全网络把导管铺满，每个冲击的边际清算需求小；稀疏网络把导管收成少数边，边上流量一大就触发火灾出售。价格渠道与债权渠道可以分开：即使没有直接互存，火灾出售压低共同持有的资产价格，也会改写另一家的偿付能力。</p><p>这与<a href="/econ/akerlof-lemons">柠檬</a>不同：资产质量可以透明，价格下跌仍来自强制出售。也与单家 Diamond–Dybvig 不同：本行耐心者即使仍相信本行合同，也会因为对手违约而失去流动性保险，于是最优反应改变。系统性风险因此是网络与清算折扣的产物，不是把「恐慌」乘以 \\(N\\)。</p><h3 id="共同冲击不是传染" tabindex="-1">共同冲击不是传染 <a class="header-anchor" href="#共同冲击不是传染" aria-label="Permalink to &quot;共同冲击不是传染&quot;">​</a></h3><p>许多银行同时面对同一宏观违约，是共同因子，不是传染。Allen–Gale 要识别的是：<strong>在共同因子之外</strong>，一家的提前清算是否改变另一家的约束。经验上两者缠在一起，理论必须先分开。本课禁止用「系统性」一词把共同冲击与网络传递混成一个故事。</p><p><span class="marginnote">不完全市场在这里是银行间债权的稀疏，不是 Arrow–Debreu 证券的缺失本身。区域冲击不可用对公众发行的或有要求权完美对冲，才需要银行间互存。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把批发融资挤兑、货币市场基金赎回直接写成 2000 年的定理。那些是同一转换换了一张负债；机制同构，模型不是同一篇。也不要把资本充足当成已经解决传染：资本吸收的是亏损顺序，网络决定亏损写到谁的表上。下一课的<a href="/econ/deposit-insurance">存款保险</a>删单家坏均衡，但对未保险的银行间债权不必自动删传染。</p><p>本课不写巴塞尔风险权重，不写太大而不能倒的隐担保。后两块分别改变「倒闭的社会成本被私人内部化了多少」，不是本课的网络会计。</p><p>后课默认：单家挤兑可以经由不完全的银行间保险导入邻居。完全网络分摊，稀疏网络放大清算折扣。共同冲击与传染必须分开写。</p><p>保险网络同时是损失导管。稀疏边上的流量一大，就会把 Diamond–Dybvig 的坏均衡做成系统事件。</p><p>不要用「系统性」吞掉共同因子。传递边必须可指认。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>单家活期合同允许挤兑；银行间互存把挤兑写成邻居的约束。</li><li>完全网络分摊区域冲击；不完全网络沿边导入清算与挤兑。</li><li>系统性是网络加折扣，不是把恐慌乘以银行家数。</li><li>出处：Allen and Gale, <em>JPE</em> 2000；对照 Freixas, Parigi and Rochet 的支付暴露。</li></ul>',15))])}const b=r(c,[["render",h]]);export{f as __pageData,b as default};
